import os
import ast

def inspect_files():
    app_dir = "app"
    for root, dirs, files in os.walk(app_dir):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                code = f.read()

            try:
                tree = ast.parse(code)
            except Exception as e:
                print(f"Failed to parse {path}: {e}")
                continue

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    # Check if legacy_auth is in this function
                    has_legacy_auth = False
                    for subnode in ast.walk(node):
                        if isinstance(subnode, ast.Call):
                            if isinstance(subnode.func, ast.Name) and subnode.func.id == "legacy_auth":
                                has_legacy_auth = True
                                break
                    if has_legacy_auth:
                        print("="*60)
                        print(f"File: {path}")
                        print(f"Function: {node.name}")
                        # Get function source code
                        lines = code.splitlines()
                        func_code = "\n".join(lines[node.lineno - 1 : node.end_lineno])
                        print(func_code)

if __name__ == "__main__":
    inspect_files()

