import os
import ast
import re

KEYWORDS = [
    "create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"
]

def analyze_write_read():
    app_dir = "app"
    for root, dirs, files in os.walk(app_dir):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                code = f.read()

            try:
                tree = ast.parse(code)
            except Exception as e:
                continue

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    has_legacy_auth = False
                    for subnode in ast.walk(node):
                        if isinstance(subnode, ast.Call):
                            if isinstance(subnode.func, ast.Name) and subnode.func.id == "legacy_auth":
                                has_legacy_auth = True
                                break
                    if has_legacy_auth:
                        func_code = ast.get_source_segment(code, node) or ""
                        # Also check the file path itself, or just the function code?
                        # Let's search for keywords in the function code or file path
                        found_kw = []
                        for kw in KEYWORDS:
                            if kw in func_code or kw in path:
                                found_kw.append(kw)

                        # Let's see if there are any other write indicators
                        scope = "write" if found_kw else "read"
                        print(f"Path: {path} | Func: {node.name} | Scope: {scope} | KWs: {found_kw}")

if __name__ == "__main__":
    analyze_write_read()

import os
import ast

RELAXED_KEYWORDS = [
    "create", "update", "delete", "save", "write", "post", "put", "patch"
]

def analyze_write_read_relaxed():
    app_dir = "app"
    for root, dirs, files in os.walk(app_dir):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                code = f.read()

            try:
                tree = ast.parse(code)
            except Exception as e:
                continue

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    has_legacy_auth = False
                    for subnode in ast.walk(node):
                        if isinstance(subnode, ast.Call):
                            if isinstance(subnode.func, ast.Name) and subnode.func.id == "legacy_auth":
                                has_legacy_auth = True
                                break
                    if has_legacy_auth:
                        func_code = ast.get_source_segment(code, node) or ""

                        found_in_func = []
                        for kw in RELAXED_KEYWORDS:
                            if kw in func_code.lower():
                                found_in_func.append(kw)

                        found_in_path = []
                        for kw in RELAXED_KEYWORDS:
                            if kw in path.lower():
                                found_in_path.append(kw)

                        print(f"Path: {path} | Func: {node.name} | PathKWs: {found_in_path} | FuncKWs: {found_in_func}")

if __name__ == "__main__":
    analyze_write_read_relaxed()
